import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { useSound } from "./sound-provider";

// Airbnb Button — extracted from airbnb.com (2026-04)
// Primary: solid #FF385C, radial gradient on hover
// Secondary: #222 solid
// Outline: white bg, 1px #222 border
// Rounded: 8px default, pill for search CTA
// No drop-shadow on buttons — flat with border or solid fill

const buttonVariants = cva(
  [
    "relative inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "text-sm font-semibold",
    "rounded-lg transition-all duration-fast ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
    "active:scale-[0.98]",
  ].join(" "),
  {
    variants: {
      variant: {
        // Rausch solid — radial gradient on hover
        default:
          "bg-primary text-primary-foreground " +
          "hover:bg-primary/90",
        // Dark — #222 solid
        secondary:
          "bg-secondary text-secondary-foreground " +
          "hover:bg-[oklch(0_0_0)]",
        // Outline — white bg, thin dark border
        outline:
          "border border-foreground bg-background text-foreground " +
          "hover:bg-muted",
        // Ghost: no border and no fill until hover
        ghost:
          "bg-transparent text-foreground " +
          "hover:bg-muted",
        // Destructive
        destructive:
          "bg-destructive text-destructive-foreground " +
          "hover:bg-destructive/90",
        // Link
        link: "text-foreground underline-offset-4 underline hover:text-foreground/80",
      },
      size: {
        default: "h-12 px-6 py-3",
        sm: "h-9 px-4 text-xs rounded-lg",
        lg: "h-14 px-8 text-base rounded-xl",
        icon: "h-10 w-10 rounded-full",
        "icon-sm": "h-9 w-9 rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string;
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, onClick, onPointerDown, ...props }, ref) => {
    // Callers written against the Radix API pass the element to become as a
    // child: <Button asChild><Link>…</Link></Button>. Base UI has no asChild,
    // it composes through `render`. Without this the prop reaches the DOM and
    // the anchor nests inside the button instead of replacing it, which stacks
    // the icon above the label and puts a link inside a button.
    if (asChild && React.isValidElement(props.children)) {
      const { children, ...rest } = props
      return (
        <ButtonPrimitive
          ref={ref}
          className={cn(buttonVariants({ variant, size, className }))}
          {...rest}
          // After the spread, so an explicit asChild child wins over a stray
          // render prop rather than being silently replaced by it.
          // SAFETY: this branch runs only when `asChild` is set, and the caller then
          // owns passing a single element for the slot to clone.
          render={children as React.ReactElement}
        />
      );
    }

    const { playClick, playTick } = useSound();
    return (
      <ButtonPrimitive
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        onPointerDown={(e) => {
          playTick();
          onPointerDown?.(e);
        }}
        onClick={(e) => {
          playClick();
          onClick?.(e);
        }}
        {...props}
      />
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };
